"""Write .env with random secrets for docker compose (see .env.example).

Refuses to overwrite an existing .env, so running it twice can't lock you out of the
database volume, whose password was fixed when it was first created.

Run:  python scripts/make_env.py
"""

from __future__ import annotations

import hashlib
import secrets
from pathlib import Path


def main() -> None:
    env = Path(".env")
    if env.exists():
        raise SystemExit(".env already exists; edit it by hand or delete it first")
    key = secrets.token_urlsafe(24)
    env.write_text(
        "# Generated by scripts/make_env.py; never commit this file.\n"
        "POSTGRES_USER=spatify\n"
        f"POSTGRES_PASSWORD={secrets.token_hex(16)}\n"
        f"SPATIFY_API_KEY={key}\n"
        f"API_KEY_SHA256={hashlib.sha256(key.encode()).hexdigest()}\n"
    )
    env.chmod(0o600)
    print("Wrote .env; the admin key is SPATIFY_API_KEY in that file")


if __name__ == "__main__":
    main()
